'use strict';

/**
 * CodeLens AI - Skill Gap Mapping
 *
 * Deterministic mapping from normalized finding types
 * to developer learning areas and curated resources.
 *
 * Resource URLs are static/curated.
 * They are NOT generated by an LLM.
 */

const SKILL_GAP_MAPPING = Object.freeze({
  SQL_INJECTION: Object.freeze({
    skill: 'Parameterized queries / SQL injection prevention',
    resources: Object.freeze([
      {
        title: 'OWASP SQL Injection Prevention Cheat Sheet',
        url: 'https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html'
      }
    ])
  }),

  HARDCODED_SECRET: Object.freeze({
    skill: 'Secret management',
    resources: Object.freeze([
      {
        title: 'OWASP Secrets Management Cheat Sheet',
        url: 'https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html'
      }
    ])
  }),

  COMMAND_INJECTION: Object.freeze({
    skill: 'Safe command execution',
    resources: Object.freeze([
      {
        title: 'OWASP OS Command Injection Defense Cheat Sheet',
        url: 'https://cheatsheetseries.owasp.org/cheatsheets/OS_Command_Injection_Defense_Cheat_Sheet.html'
      }
    ])
  }),

  MISSING_INPUT_VALIDATION: Object.freeze({
    skill: 'Input validation',
    resources: Object.freeze([
      {
        title: 'OWASP Input Validation Cheat Sheet',
        url: 'https://cheatsheetseries.owasp.org/cheatsheets/Input_Validation_Cheat_Sheet.html'
      }
    ])
  })
});

/**
 * Get skill-gap information for a normalized finding type.
 *
 * @param {string} findingType
 * @returns {Object|null}
 */
function getSkillGap(findingType) {
  if (typeof findingType !== 'string') {
    return null;
  }

  return SKILL_GAP_MAPPING[findingType] || null;
}

/**
 * Map multiple findings to unique skill gaps.
 *
 * @param {Array} findings
 * @returns {Array}
 */
function mapSkillGaps(findings) {
  if (!Array.isArray(findings)) {
    return [];
  }

  const seen = new Set();
  const skillGaps = [];

  for (const finding of findings) {
    if (!finding || typeof finding.type !== 'string') {
      continue;
    }

    if (seen.has(finding.type)) {
      continue;
    }

    const mapping = getSkillGap(finding.type);

    if (!mapping) {
      continue;
    }

    seen.add(finding.type);

    skillGaps.push({
      type: finding.type,
      skill: mapping.skill,
      resources: mapping.resources
    });
  }

  return skillGaps;
}

module.exports = {
  SKILL_GAP_MAPPING,
  getSkillGap,
  mapSkillGaps
};